86: /*
87:  * GetModuleFullName:
88:  *
89:  *    Gets the full path and file name of the specified module and returns the length on success,
90:  *    (which does not include the terminating NUL character) 0 otherwise.  Use GetLastError() to
91:  *    get extended error information.
92:  *
93:  *       hModule              [in] Handle to a module loaded by the calling process, or NULL to
94:  *                            use the current process module handle.  This function does not
95:  *                            retrieve the name for modules that were loaded using LoadLibraryEx
96:  *                            with the LOAD_LIBRARY_AS_DATAFILE flag. For more information, see
97:  *                            LoadLibraryEx.
98:  *
99:  *       pszBuffer            [out] Pointer to the buffer which receives the module full name.
100:  *                            This paramater may be NULL, in which case the function returns the
101:  *                            size of the buffer in characters required to contain the full name,
102:  *                            including a NUL terminating character.
103:  *
104:  *       nMaxChars            [in] Specifies the size of the buffer in characters.  This must be
105:  *                            0 when pszBuffer is NULL, otherwise the function fails.
106:  *
107:  *       ppszFileName         [out] On return, the referenced pointer is assigned a position in
108:  *                            the buffer to the module's file name only.  This parameter may be
109:  *                            NULL if the file name is not required.
110:  */
111: EXTERN_C int WINAPI GetModuleFullName(__in HMODULE hModule, __out LPWSTR pszBuffer,
112:                                       __in int nMaxChars, __out LPWSTR* ppszFileName)
113: {
114:     /* Determine required buffer size when requested */
115:     int nLength = 0;
116:     DWORD dwStatus = NO_ERROR;
117: 
118:     /* Validate parameters */
119:     if (dwStatus == NO_ERROR)
120:     {
121:         if (pszBuffer == NULL && (nMaxChars != 0 || ppszFileName != NULL))
122:         {
123:              dwStatus = ERROR_INVALID_PARAMETER;
124:         }
125:         else if (pszBuffer != NULL && nMaxChars < 1)
126:         {
127:              dwStatus = ERROR_INVALID_PARAMETER;
128:         }
129:     }
130: 
131:     if (dwStatus == NO_ERROR)
132:     {
133:         if (pszBuffer == NULL)
134:         {
135:             HANDLE hHeap = GetProcessHeap();
136: 
137:             WCHAR  cwBuffer[2048] = { 0 };
138:             LPWSTR pszBuffer      = cwBuffer;
139:             DWORD  dwMaxChars     = _countof(cwBuffer);
140:             DWORD  dwLength       = 0;
141: 
142:             LPWSTR pszNew;
143:             SIZE_T nSize;
144: 
145:             for (;;)
146:             {
147:                 /* Try to get the module's full path and file name */
148:                 dwLength = GetModuleFileNameW(hModule, pszBuffer, dwMaxChars);
149: 
150:                 if (dwLength == 0)
151:                 {
152:                     dwStatus = GetLastError();
153:                     break;
154:                 }
155: 
156:                 /* If succeeded, return buffer size requirement:
157:                  *    o  Adds one for the terminating NUL character.
158:                  */
159:                 if (dwLength < dwMaxChars)
160:                 {
161:                     nLength = (int)dwLength + 1;
162:                     break;
163:                 }
164: 
165:                 /* Check the maximum supported full name length:
166:                  *    o  Assumes support for HPFS, NTFS, or VTFS of ~32K.
167:                  */
168:                 if (dwMaxChars >= 32768U)
169:                 {
170:                     dwStatus = ERROR_BUFFER_OVERFLOW;
171:                     break;
172:                 }
173: 
174:                 /* Double the size of our buffer and try again */
175:                 dwMaxChars *= 2;
176: 
177:                 pszNew = (pszBuffer == cwBuffer ? NULL : pszBuffer);
178:                 nSize  = (SIZE_T)dwMaxChars * sizeof(WCHAR);
179: 
180:                 if (pszNew == NULL)
181:                 {
182:                     pszNew = (LPWSTR)HeapAlloc(hHeap, 0, nSize);
183:                 }
184:                 else
185:                 {
186:                     LPWSTR pszTmp;
187:                     pszTmp = (LPWSTR)HeapReAlloc(hHeap, 0, pszNew, nSize);
188:                     if (pszTmp == NULL)
189:                     {
190:                         HeapFree(hHeap, 0, pszNew);
191:                         if (pszNew == pszBuffer)
192:                         {
193:                             pszBuffer = NULL;
194:                         }
195:                         pszNew = NULL;
196:                     }
197:                     else
198:                     {
199:                         pszNew = pszTmp;
200:                     }
201:                 }
202: 
203:                 if (pszNew == NULL)
204:                 {
205:                     dwStatus = ERROR_OUTOFMEMORY;
206:                     break;
207:                 }
208: 
209:                 pszBuffer = pszNew;
210:             }
211: 
212:             /* Free the temporary buffer if allocated */
213:             if (pszBuffer != cwBuffer)
214:             {
215:                 if (!HeapFree(hHeap, 0, pszBuffer))
216:                 {
217:                    dwStatus = GetLastError();
218:                 }
219:             }
220:         }
221:     }
222: 
223:     /* Get the module's full name and pointer to file name when requested */
224:     if (dwStatus == NO_ERROR)
225:     {
226:         if (pszBuffer != NULL)
227:         {
228:             nLength = (int)GetModuleFileNameW(hModule, pszBuffer, nMaxChars);
229: 
230:             if (nLength <= 0 || nLength == nMaxChars)
231:             {
232:                 dwStatus = GetLastError();
233:             }
234:             else if (ppszFileName != NULL)
235:             {
236:                 LPWSTR pszItr;
237:                 *ppszFileName = pszBuffer;
238: 
239:                 for (pszItr = pszBuffer; *pszItr != L'\0'; ++pszItr)
240:                 {
241:                     if (*pszItr == L'\\' || *pszItr == L'/')
242:                     {
243:                         *ppszFileName = pszItr + 1;
244:                     }
245:                }
246:             }
247:          }
248:     }
249: 
250:     /* Return full name length or 0 on error */
251:     if (dwStatus != NO_ERROR)
252:     {
253:         nLength = 0;
254: 
255:         SetLastError(dwStatus);
256:     }
257: 
258:     return nLength;
259: }
