297:     if (strncmp(data->filename, "-", 2) == 0)
298:     {
299:         /* Need to create pipe */
300:         WCHAR *tmp;
301:         int nChars = sizeof("\\\\.\\pipe\\") + strlen(data->device) + 1;
302:         pipeName = malloc((nChars + 1) * sizeof(WCHAR));
303:         if (pipeName == NULL)
304:         {
305:             fprintf(stderr, "Failed to allocate pipe name\n");
306:             free(exePath);
307:             return FALSE;
308:         }
309:         swprintf_s(pipeName, nChars,  L"\\\\.\\pipe\\%S", data->device);
310:         for (tmp = &pipeName[sizeof("\\\\.\\pipe\\")]; *tmp; tmp++)
311:         {
312:             if (*tmp == L'\\')
313:             {
314:                 *tmp = L'_';
315:             }
316:         }
317: 
318:         *pcap_handle = CreateNamedPipeW(pipeName,
319:                                         /* Pipe is used for elevated worker -> caller process communication.
320:                                          * It is full duplex to allow caller to notice elevated worker that
321:                                          * it should terminate (read from this pipe in elevated worker will
322:                                          * result in ERROR_BROKEN_PIPE).
323:                                          */
324:                                         PIPE_ACCESS_DUPLEX | FILE_FLAG_FIRST_PIPE_INSTANCE | FILE_FLAG_OVERLAPPED,
325:                                         PIPE_TYPE_BYTE | PIPE_READMODE_BYTE | PIPE_WAIT,
326:                                         2 /* Max instances of pipe */,
327:                                         data->bufferlen, data->bufferlen,
328:                                         0, NULL);
329: 
330: 
331:         if (*pcap_handle == INVALID_HANDLE_VALUE)
332:         {
333:             fprintf(stderr, "Failed to create named pipe - %d\n", GetLastError());
334:             free(exePath);
335:             free(pipeName);
336:             return FALSE;
337:         }
338:     }
339:     else
340:     {
341:         *pcap_handle = INVALID_HANDLE_VALUE;
342:     }
343: 
344: #define WORKER_CMD_LINE_FORMATTER             L"-d %S -b %u -o %S"
345: #define WORKER_CMD_LINE_FORMATTER_PIPE        L"-d %S -b %u -o %s"
346: 
347: #define WORKER_CMD_LINE_FORMATTER_SNAPLEN     L" -s %u"
348: #define WORKER_CMD_LINE_FORMATTER_DEVICES     L" --devices %S"
349: #define WORKER_CMD_LINE_FORMATTER_CAPTURE_ALL L" --capture-from-all-devices"
350: #define WORKER_CMD_LINE_FORMATTER_CAPTURE_NEW L" --capture-from-new-devices"
351: #define WORKER_CMD_LINE_FORMATTER_INJECT_DESCRIPTORS L" --inject-descriptors"
352: 
353:     cmdLineLen = MultiByteToWideChar(CP_ACP, 0, data->device, -1, NULL, 0);
354:     cmdLineLen += (pipeName == NULL) ? strlen(data->filename) : wcslen(pipeName);
355:     cmdLineLen += wcslen(WORKER_CMD_LINE_FORMATTER);
356:     cmdLineLen += 9 /* maximum bufferlen in characters */;
357:     cmdLineLen += 1 /* NULL termination */;
358:     cmdLineLen += wcslen(WORKER_CMD_LINE_FORMATTER_SNAPLEN);
359:     cmdLineLen += 10 /* maximum snaplen in characters */;
360:     cmdLineLen += wcslen(WORKER_CMD_LINE_FORMATTER_DEVICES);
361:     cmdLineLen += wcslen(WORKER_CMD_LINE_FORMATTER_CAPTURE_ALL);
362:     cmdLineLen += wcslen(WORKER_CMD_LINE_FORMATTER_CAPTURE_NEW);
363:     cmdLineLen += wcslen(WORKER_CMD_LINE_FORMATTER_INJECT_DESCRIPTORS);
364:     cmdLineLen += (data->address_list == NULL) ? 0 : strlen(data->address_list);
365: 
366:     cmdLine = (PWSTR)malloc(cmdLineLen * sizeof(WCHAR));
367: 
368:     if (cmdLine == NULL)
369:     {
370:         fprintf(stderr, "Failed to allocate command line\n");
371:         free(exePath);
372:         free(pipeName);
373:         return FALSE;
374:     }
375: 
376:     if (pipeName == NULL)
377:     {
378:         nChars = swprintf_s(cmdLine,
379:                             cmdLineLen,
380:                             WORKER_CMD_LINE_FORMATTER,
381:                             data->device,
382:                             data->bufferlen,
383:                             data->filename);
384:     }
385:     else
386:     {
387:         nChars = swprintf_s(cmdLine,
388:                             cmdLineLen,
389:                             WORKER_CMD_LINE_FORMATTER_PIPE,
390:                             data->device,
391:                             data->bufferlen,
392:                             pipeName);
393:     }
394: 
395:     if (data->snaplen != DEFAULT_SNAPSHOT_LENGTH)
396:     {
397:         nChars += swprintf_s(&cmdLine[nChars],
398:                              cmdLineLen - nChars,
399:                              WORKER_CMD_LINE_FORMATTER_SNAPLEN,
400:                              data->snaplen);
401:     }
402: 
403:     if (data->address_list != NULL)
404:     {
405:         nChars += swprintf_s(&cmdLine[nChars],
406:                              cmdLineLen - nChars,
407:                              WORKER_CMD_LINE_FORMATTER_DEVICES,
408:                              data->address_list);
409:     }
410: 
411:     if (data->capture_all)
412:     {
413:         nChars += swprintf_s(&cmdLine[nChars],
414:                              cmdLineLen - nChars,
415:                              WORKER_CMD_LINE_FORMATTER_CAPTURE_ALL);
416:     }
417: 
418:     if (data->capture_new)
419:     {
420:         nChars += swprintf_s(&cmdLine[nChars],
421:                              cmdLineLen - nChars,
422:                              WORKER_CMD_LINE_FORMATTER_CAPTURE_NEW);
423:     }
424: 
425:     if (data->inject_descriptors)
426:     {
427:         nChars += swprintf_s(&cmdLine[nChars],
428:                              cmdLineLen - nChars,
429:                              WORKER_CMD_LINE_FORMATTER_INJECT_DESCRIPTORS);
430:     }
431: #undef WORKER_CMD_LINE_FORMATTER_PIPE
432: #undef WORKER_CMD_LINE_FORMATTER
433: 
434: #undef WORKER_CMD_LINE_FORMATTER_INJECT_DESCRIPTORS
435: #undef WORKER_CMD_LINE_FORMATTER_CAPTURE_NEW
436: #undef WORKER_CMD_LINE_FORMATTER_CAPTURE_ALL
437: #undef WORKER_CMD_LINE_FORMATTER_DEVICES
438: #undef WORKER_CMD_LINE_FORMATTER_SNAPLEN
439: 
440:     free(pipeName);
441: 
442:     *appPath = exePath;
443:     *appCmdLine = cmdLine;
444:     return TRUE;
445: }
