447: /**
448:  *  Creates elevated worker process.
449:  *
450:  *  \param[in] appPath path to elevated worker module
451:  *  \param[in] cmdLine commandline to start elevated worker with
452:  *
453:  *  \return Handle to created process.
454:  */
455: static HANDLE create_elevated_worker(PWSTR appPath, PWSTR cmdLine)
456: {
457:     BOOL bSuccess = FALSE;
458:     SHELLEXECUTEINFOW exInfo = { 0 };
459: 
460:     exInfo.cbSize = sizeof(exInfo);
461:     exInfo.fMask = SEE_MASK_NOCLOSEPROCESS | SEE_MASK_NO_CONSOLE;
462:     exInfo.hwnd = NULL;
463:     exInfo.lpVerb = L"runas";
464:     exInfo.lpFile = appPath;
465:     exInfo.lpParameters = cmdLine;
466:     exInfo.lpDirectory = NULL;
467:     exInfo.nShow = SW_HIDE;
468:     /* exInfo.hInstApp is output parameter */
469:     /* exInfo.lpIDList, exInfo.lpClass, exInfo.hkeyClass, exInfo.dwHotKey, exInfo.DUMMYUNIONNAME
470:      * are ignored for our fMask value.
471:      */
472:     /* exInfo.hProcess is output parameter */
473: 
474:     bSuccess = ShellExecuteExW(&exInfo);
475: 
476:     if (FALSE == bSuccess)
477:     {
478:         fprintf(stderr, "Failed to create worker process!\n");
479:         return INVALID_HANDLE_VALUE;
480:     }
481: 
482:     return exInfo.hProcess;
483: }
