485: /**
486:  *  Creates intermediate worker process that creates elevated worker process
487:  *  inside a job that will terminate all processes on close.
488:  *
489:  *  On success it modifies data->worker_process_thread handle.
490:  *
491:  *  \param[inout] data thread_data containing capture configuration.
492:  *  \param[in] appPath path to elevated worker module
493:  *  \param[in] cmdLine commandline to start elevated worker with
494:  *
495:  *  \return Handle to created process.
496:  */
497: static HANDLE create_breakaway_worker_in_job(struct thread_data *data, PWSTR appPath, PWSTR appCmdLine)
498: {
499:     HANDLE process = INVALID_HANDLE_VALUE;
500:     STARTUPINFOW startupInfo;
501:     PROCESS_INFORMATION processInfo;
502:     PWSTR processCmdLine;
503:     int nChars;
504: 
505:     if (data->job_handle == INVALID_HANDLE_VALUE)
506:     {
507:         fprintf(stderr, "create_breakaway_worker_in_job() cannot be called if data->job_handle is INVALID_HANDLE_VALUE!\n");
508:         return INVALID_HANDLE_VALUE;
509:     }
510: 
511:     memset(&startupInfo, 0, sizeof(startupInfo));
512:     startupInfo.cb = sizeof(startupInfo);
513:     startupInfo.dwFlags = STARTF_USESHOWWINDOW;
514:     startupInfo.wShowWindow = SW_HIDE;
515: 
516:     /* CreateProcessW works different to ShellExecuteExW.
517:      * It will always treat first token of command line as argv[0] in
518:      * created process.
519:      *
520:      * Hence create new string that will contain "appPath" appCmdLine.
521:      */
522:     nChars = wcslen(appPath) + wcslen(appCmdLine) +
523:              4 /* Two quotemarks, one space and NULL-terminator */;
524:     processCmdLine = (PWSTR)malloc(nChars * sizeof(WCHAR));
525:     if (processCmdLine == NULL)
526:     {
527:         fprintf(stderr, "Failed to allocate memory for processCmdLine!\n");
528:         return INVALID_HANDLE_VALUE;
529:     }
530: 
531:     swprintf_s(processCmdLine, nChars, L"\"%s\" %s",
532:                appPath, appCmdLine);
533: 
534:     /* We need to breakaway from parent job and assign to data->job_handle. */
535:     if (0 == CreateProcessW(NULL, processCmdLine, NULL, NULL, FALSE,
536:                             CREATE_BREAKAWAY_FROM_JOB | CREATE_SUSPENDED,
537:                             NULL, NULL, &startupInfo, &processInfo))
538:     {
539:         data->process = FALSE;
540:     }
541:     else
542:     {
543:         process = processInfo.hProcess;
544:         /* processInfo.hThread needs to be closed. */
545:         data->worker_process_thread = processInfo.hThread;
546: 
547:         /* process is not assigned to any job. Assign it. */
548:         if (AssignProcessToJobObject(data->job_handle, process) == FALSE)
549:         {
550:             fprintf(stderr, "Failed to Assign process to job object - %d\n",
551:                     GetLastError());
552:             /* This is fatal error. */
553:             CloseHandle(process);
554:             CloseHandle(data->worker_process_thread);
555:             data->process = FALSE;
556:             process = INVALID_HANDLE_VALUE;
557:             data->worker_process_thread = INVALID_HANDLE_VALUE;
558:         }
559:         else
560:         {
561:             /* Process is assigned to proper job. Resume it. */
562:             ResumeThread(data->worker_process_thread);
563:         }
564:     }
565: 
566:     free(processCmdLine);
567: 
568:     return process;
569: }
