571: int cmd_interactive(struct thread_data *data)
572: {
573:     int i = 0;
574:     int max_i;
575:     char buffer[INPUT_BUFFER_SIZE];
576:     BOOL finished;
577:     BOOL exit = FALSE;
578: 
579:     /* Detach from parent console window. Make sure to reopen stdout
580:      * and stderr as otherwise wide_print() does not corectly detect
581:      * console.
582:      */
583:     FreeConsole();
584:     freopen("CONOUT$", "w", stdout);
585:     freopen("CONOUT$", "w", stderr);
586:     /* If we are running interactive then we should show console window.
587:      * We are not automatically allocated a console window because the
588:      * application type is set to windows. This prevents console
589:      * window from showing when USBPcapCMD is used as extcap.
590:      * Since extcap is recommended cmd.exe users will notice a slight
591:      * inconvenience that USBPcapCMD opens new window.
592:      *
593:      * Please note that is it impossible to get parent's cmd.exe stdin
594:      * handle if application type is not console. The difference is
595:      * that in case of console application cmd.exe waits until the
596:      * process finishes and in case of windows applications there is
597:      * no wait for process termination and the cmd.exe console immadietely
598:      * regains standard input functionality.
599:      */
600:     if (AllocConsole() == FALSE)
601:     {
602:         return -1;
603:     }
604: 
605:     freopen("CONIN$", "r", stdin);
606:     freopen("CONOUT$", "w", stdout);
607:     freopen("CONOUT$", "w", stderr);
608: 
609:     data->filename = NULL;
610:     data->capture_all = TRUE;
611:     data->inject_descriptors = TRUE;
612: 
613:     filters_initialize();
614:     if (usbpcapFilters[0] == NULL)
615:     {
616:         printf("No filter control devices are available.\n");
617: 
618:         if (is_usbpcap_upper_filter_installed() == FALSE)
619:         {
620:             printf("Please reinstall USBPcapDriver.\n");
621:             (void)getchar();
622:             filters_free();
623:             return -1;
624:         }
625: 
626:         printf("USBPcap UpperFilter entry appears to be present.\n"
627:                "Most likely you have not restarted your computer after installation.\n"
628:                "It is possible to restart all USB devices to get USBPcap working without reboot.\n"
629:                "\nWARNING:\n  Restarting all USB devices can result in data loss.\n"
630:                "  If you are unsure please answer 'n' and reboot in order to use USBPcap.\n\n");
631: 
632:         finished = FALSE;
633:         do
634:         {
635:             printf("Do you want to restart all USB devices (y, n)? ");
636:             if (fgets(buffer, INPUT_BUFFER_SIZE, stdin) == NULL)
637:             {
638:                 printf("Invalid input\n");
639:             }
640:             else
641:             {
642:                 if (buffer[0] == 'y')
643:                 {
644:                     finished = TRUE;
645:                     restart_all_usb_devices();
646:                     filters_free();
647:                     filters_initialize();
648:                 }
649:                 else if (buffer[0] == 'n')
650:                 {
651:                     filters_free();
652:                     return -1;
653:                 }
654:             }
655:         } while (finished == FALSE);
656:     }
657: 
658:     printf("Following filter control devices are available:\n");
659:     while (usbpcapFilters[i] != NULL)
660:     {
661:         printf("%d %s\n", i+1, usbpcapFilters[i]->device);
662:         enumerate_print_usbpcap_interactive(usbpcapFilters[i]->device);
663:         i++;
664:     }
665: 
666:     max_i = i;
667: 
668:     finished = FALSE;
669:     do
670:     {
671:         printf("Select filter to monitor (q to quit): ");
672:         if (fgets(buffer, INPUT_BUFFER_SIZE, stdin) == NULL)
673:         {
674:             printf("Invalid input\n");
675:         }
676:         else
677:         {
678:             if (buffer[0] == 'q')
679:             {
680:                 finished = TRUE;
681:                 exit = TRUE;
682:             }
683:             else
684:             {
685:                 int value = atoi(buffer);
686: 
687:                 if (value <= 0 || value > max_i)
688:                 {
689:                     printf("Invalid input\n");
690:                 }
691:                 else
692:                 {
693:                     data->device = _strdup(usbpcapFilters[value-1]->device);
694:                     finished = TRUE;
695:                 }
696:             }
697:         }
698:     } while (finished == FALSE);
699: 
700:     if (exit == TRUE)
701:     {
702:         filters_free();
703:         return -1;
704:     }
705: 
706:     finished = FALSE;
707:     do
708:     {
709:         printf("Output file name (.pcap): ");
710:         if (fgets(buffer, INPUT_BUFFER_SIZE, stdin) == NULL)
711:         {
712:             printf("Invalid input\n");
713:         }
714:         else if (buffer[0] == '\0')
715:         {
716:             printf("Empty filename not allowed\n");
717:         }
718:         else
719:         {
720:             for (i = 0; i < INPUT_BUFFER_SIZE; i++)
721:             {
722:                 if (buffer[i] == '\n')
723:                 {
724:                     buffer[i] = '\0';
725:                     break;
726:                 }
727:             }
728:             data->filename = _strdup(buffer);
729:             finished = TRUE;
730:         }
731:     } while (finished == FALSE);
732: 
733:     filters_free();
734:     return 0;
735: }
