737: /**
738:  * Wait for exit signal.
739:  *
740:  * Wait for either 'q' on standard input, data->exit_event or worker process termination.
741:  *
742:  * \param[in] data Thread data structure
743:  * \param[in] process Worker process handle
744:  *                    INVALID_HANDLE_VALUE if not using elevated worker.
745:  */
746: static void wait_for_exit_signal(struct thread_data *data, HANDLE process)
747: {
748:     HANDLE handle_table[3] = {INVALID_HANDLE_VALUE, INVALID_HANDLE_VALUE, INVALID_HANDLE_VALUE};
749:     HANDLE stdin_handle = GetStdHandle(STD_INPUT_HANDLE);
750:     DWORD dw;
751:     int count = 0;
752: 
753:     /* Verify that stdin_handle can be used. */
754:     if ((stdin_handle != NULL) && (stdin_handle != INVALID_HANDLE_VALUE))
755:     {
756:         dw = WaitForSingleObject(stdin_handle, 0);
757:         if (dw != WAIT_FAILED)
758:         {
759:             handle_table[count] = stdin_handle;
760:             count++;
761:         }
762:     }
763: 
764:     if ((data->exit_event != NULL) && (data->exit_event != INVALID_HANDLE_VALUE))
765:     {
766:         handle_table[count] = data->exit_event;
767:         count++;
768:     }
769: 
770:     if ((process != NULL) && (process != INVALID_HANDLE_VALUE))
771:     {
772:         handle_table[count] = process;
773:         count++;
774:     }
775: 
776:     if (count == 0)
777:     {
778:         fprintf(stderr, "Nothing to wait for in wait_for_exit_signal().\n");
779:     }
780: 
781:     /* Wait for exit condition. */
782:     while (data->process == TRUE)
783:     {
784:         dw = WaitForMultipleObjects(count, handle_table, FALSE, INFINITE);
785: #pragma warning(default : 4296)
786:         if ((dw >= WAIT_OBJECT_0) && dw < (WAIT_OBJECT_0 + count))
787:         {
788:             int i = dw - WAIT_OBJECT_0;
789:             if (handle_table[i] == stdin_handle)
790:             {
791:                 /* There is something new on standard input. */
792:                 INPUT_RECORD record;
793:                 DWORD events_read;
794: 
795:                 if (ReadConsoleInput(stdin_handle, &record, 1, &events_read))
796:                 {
797:                     if (record.EventType == KEY_EVENT)
798:                     {
799:                         if ((record.Event.KeyEvent.bKeyDown == TRUE) &&
800:                             (record.Event.KeyEvent.uChar.AsciiChar == 'q'))
801:                         {
802:                             /* There is 'q' on standard input. Quit. */
803:                             break;
804:                         }
805:                     }
806:                 }
807:             }
808:             else if (handle_table[i] == process)
809:             {
810:                 /* Elevated worker process terminated. Quit. */
811:                 break;
812:             }
813:             else if (handle_table[i] == data->exit_event)
814:             {
815:                 /* Read thread has finished. Quit. */
816:                 break;
817:             }
818:         }
819:         else if (dw == WAIT_FAILED)
820:         {
821:             fprintf(stderr, "WaitForMultipleObjects failed in wait_for_exit_signal(): %d\n", GetLastError());
822:             break;
823:         }
824:     }
825: }
