827: static void start_capture(struct thread_data *data)
828: {
829:     HANDLE pipe_handle = INVALID_HANDLE_VALUE;
830:     HANDLE process = INVALID_HANDLE_VALUE;
831:     HANDLE thread = NULL;
832:     DWORD thread_id;
833: 
834:     /* Sanity check capture configuration. */
835:     if ((data->capture_all == FALSE) &&
836:         (data->capture_new == FALSE) &&
837:         (data->address_list == NULL))
838:     {
839:         fprintf(stderr, "Selected capture options result in empty capture.\n");
840:         fprintf(stderr, "Add command-line option -A to capture from all devices.\n");
841:         return;
842:     }
843: 
844:     if (FALSE == USBPcapInitAddressFilter(&data->filter, data->address_list, data->capture_all))
845:     {
846:         fprintf(stderr, "USBPcapInitAddressFilter failed!\n");
847:         return;
848:     }
849: 
850:     data->exit_event = CreateEvent(NULL, /* Handle cannot be inherited */
851:                                    TRUE, /* Manual Reset */
852:                                    FALSE, /* Default to not signalled */
853:                                    NULL);
854: 
855:     memset(&data->descriptors, 0, sizeof(data->descriptors));
856: 
857:     if (IsElevated() == TRUE)
858:     {
859:         data->read_handle = INVALID_HANDLE_VALUE;
860:         if (strncmp("-", data->filename, 2) == 0)
861:         {
862:             data->write_handle = GetStdHandle(STD_OUTPUT_HANDLE);
863:         }
864:         else
865:         {
866:             data->write_handle = CreateFileA(data->filename,
867:                                              GENERIC_WRITE,
868:                                              0,
869:                                              NULL,
870:                                              CREATE_NEW,
871:                                              FILE_ATTRIBUTE_NORMAL|FILE_FLAG_OVERLAPPED,
872:                                              NULL);
873:         }
874: 
875:         if (data->inject_descriptors)
876:         {
877:             data->descriptors.descriptors = descriptors_generate_pcap(data->device, &data->descriptors.descriptors_len,
878:                                                                       &data->filter);
879:             data->descriptors.buf_written = 0;
880:         }
881: 
882:         data->read_handle = create_filter_read_handle(data);
883: 
884:         thread = CreateThread(NULL, /* default security attributes */
885:                               0,    /* use default stack size */
886:                               read_thread,
887:                               data,
888:                               0,    /* use default creation flag */
889:                               &thread_id);
890: 
891:         if (thread == NULL)
892:         {
893:             fprintf(stderr, "Failed to create thread\n");
894:             data->process = FALSE;
895:         }
896:     }
897:     else
898:     {
899:         PWSTR appPath = NULL;
900:         PWSTR appCmdLine = NULL;
901: 
902:         BOOL in_job = FALSE;
903: 
904:         if (FALSE == generate_worker_command_line(data, &appPath, &appCmdLine, &pipe_handle))
905:         {
906:             fprintf(stderr, "Failed to generate command line\n");
907:             data->process = FALSE;
908:         }
909:         else
910:         {
911:             /* Default state is USBPcapCMD running outside any job and hence
912:              * we need to create new job to take care of worker processes.
913:              */
914:             BOOL needs_breakaway = FALSE;
915:             BOOL needs_new_job = TRUE;
916: 
917:             /* We are not elevated. Check if we are running inside a job. */
918:             IsProcessInJob(GetCurrentProcess(), NULL, &in_job);
919: 
920:             if (in_job)
921:             {
922:                 /* We are running inside a job. This can be Visual Studio debug session
923:                  * job or Windows 8.1 Wireshark job or USBPcap job or anything else.
924:                  *
925:                  * If the job has JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE, then assume
926:                  * that whoever create the job will get care of any dangling processes.
927:                  *
928:                  * If the job has JOB_OBJECT_LIMIT_BREAKAWAY_OK (which is the case for
929:                  * Visual Studio and Windows 8.1 jobs) then we need to create intermediate
930:                  * worker to launch elevated worker. The intermediate worker needs to
931:                  * break from parent job.
932:                  *
933:                  * If the job has JOB_OBJECT_LIMIT_SILENT_BREAKAWAY_OK we could omit
934:                  * the intermediate worker, but keep it there so there's no race condion
935:                  * (if parent gets terminated after executing elevated worker but before
936:                  * the elevated worker is assigned to a job, then the elevated worker
937:                  * will need to be manually terminated). If we are not running inside
938:                  * a job this race condition is not a problem because we first assign
939:                  * our process to a job (and hence all newly created processes are
940:                  * automatically assigned to that job).
941:                  *
942:                  *
943:                  * All this is because ShellExecuteEx() does not support
944:                  * CREATE_BREAKAWAY_FROM_JOB nor CREATE_SUSPENDED flags.
945:                  * CreateProcess() supports CREATE_BREAKAWAY_FROM_JOB and CREATE_SUSPENDED
946:                  * flag but do not support "runas" option. USBPcapCMD manifest does not
947:                  * require administrator access because that would result in UAC screen
948:                  * every time Wireshark gets extcap interface options.
949:                  */
950: 
951:                 JOBOBJECT_EXTENDED_LIMIT_INFORMATION info;
952: 
953:                 memset(&info, 0, sizeof(info));
954:                 if (0 == QueryInformationJobObject(NULL, JobObjectExtendedLimitInformation,
