964:                     /* There is no need to breakaway nor to create new job. */
965:                     needs_breakaway = FALSE;
966:                     needs_new_job = FALSE;
967:                 }
968:                 else if (info.BasicLimitInformation.LimitFlags &
969:                          (JOB_OBJECT_LIMIT_BREAKAWAY_OK | JOB_OBJECT_LIMIT_SILENT_BREAKAWAY_OK))
970:                 {
971:                    needs_breakaway = TRUE;
972:                    needs_new_job = TRUE;
973:                 }
