995:                         return;
996:                     }
997: 
998:                     memset(&info, 0, sizeof(info));
999:                     info.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
1000:                     SetInformationJobObject(data->job_handle, JobObjectExtendedLimitInformation, &info, sizeof(info));
1001:                 }
1002: 
1003:                 /* If breakaway is not needed for worker process, then assign ourselves to newly created job.
1004:                  * This will result in automatic worker process assignment to newly created job.
1005:                  */
1006:                 if (needs_breakaway == FALSE)
1007:                 {
1008:                     if (AssignProcessToJobObject(data->job_handle, GetCurrentProcess()) == FALSE)
1009:                     {
1010:                         fprintf(stderr, "Failed to Assign process to job object - %d\n",
1011:                                 GetLastError());
1012:                         /* This is fatal error. */
1013:                         exit(-1);
1014:                     }
1015:                 }
1016:             }
1017: 
1018:             if (needs_breakaway == FALSE)
1019:             {
1020:                 /* Create elevated worker process. It will automatically be assigned to proper job. */
1021:                 process = create_elevated_worker(appPath, appCmdLine);
1022:             }
1023:             else
1024:             {
1025:                 process = create_breakaway_worker_in_job(data, appPath, appCmdLine);
1026:             }
1027: 
1028:             /* Free worker path and command line strings as these are no longer needed. */
1029:             free(appPath);
1030:             free(appCmdLine);
1031:             appPath = NULL;
1032:             appCmdLine = NULL;
1033: 
1034:             if (process != INVALID_HANDLE_VALUE)
1035:             {
1036:                 if (strncmp("-", data->filename, 2) == 0)
1037:                 {
1038:                     data->write_handle = GetStdHandle(STD_OUTPUT_HANDLE);
1039:                     data->read_handle = pipe_handle;
1040: 
1041:                     thread = CreateThread(NULL, /* default security attributes */
1042:                                           0,    /* use default stack size */
1043:                                           read_thread,
1044:                                           data,
1045:                                           0,    /* use default creation flag */
1046:                                           &thread_id);
1047:                 }
1048:                 else
1049:                 {
1050:                     /* Worker process saves directly to file */
1051:                     data->write_handle = INVALID_HANDLE_VALUE;
1052:                     data->read_handle = INVALID_HANDLE_VALUE;
1053:                 }
1054:             }
1055:             else
1056:             {
1057:                 /* Worker couldn't be started. */
1058:                 data->process = FALSE;
1059:                 if (pipe_handle != INVALID_HANDLE_VALUE)
1060:                 {
1061:                     CloseHandle(pipe_handle);
1062:                     pipe_handle = INVALID_HANDLE_VALUE;
1063:                 }
1064:             }
1065:         }
1066:     }
1067: 
1068:     wait_for_exit_signal(data, process);
1069:     data->process = FALSE;
1070:     if (data->exit_event != INVALID_HANDLE_VALUE)
1071:     {
1072:         SetEvent(data->exit_event);
1073:     }
1074: 
1075:     /* If we created worker thread, wait for it to terminate. */
1076:     if (thread != NULL)
1077:     {
1078:         WaitForSingleObject(thread, INFINITE);
1079:     }
1080: 
1081:     /* Closing read and write handles will terminate worker process. */
1082: 
1083:     if ((data->read_handle == INVALID_HANDLE_VALUE) &&
1084:         (data->write_handle == INVALID_HANDLE_VALUE))
1085:     {
1086:         /* We should kill worker process if we created it.
1087:          * We have no other way to let process know that it needs to quit.
1088:          */
1089:         if (process != INVALID_HANDLE_VALUE)
1090:         {
1091:             TerminateProcess(process, 0);
1092:         }
1093:     }
1094: 
1095:     if (data->read_handle != INVALID_HANDLE_VALUE)
1096:     {
1097:         CloseHandle(data->read_handle);
1098:     }
1099: 
1100:     if (data->write_handle != INVALID_HANDLE_VALUE)
1101:     {
1102:         CloseHandle(data->write_handle);
1103:     }
1104: 
1105:     /* If we created worker process, wait for it to terminate. */
1106:     if (process != INVALID_HANDLE_VALUE)
1107:     {
1108:         WaitForSingleObject(process, INFINITE);
1109:         CloseHandle(process);
1110:     }
1111: 
1112:     if (data->descriptors.descriptors)
1113:     {
1114:         descriptors_free_pcap(data->descriptors.descriptors);
1115:     }
