1269: static void attach_parent_console()
1270: {
1271:     HANDLE inHandle, outHandle, errHandle;
1272:     BOOL outRedirected, errRedirected;
1273: 
1274:     inHandle = GetStdHandle(STD_INPUT_HANDLE);
1275:     outHandle = GetStdHandle(STD_OUTPUT_HANDLE);
1276:     errHandle = GetStdHandle(STD_ERROR_HANDLE);
1277: 
1278:     outRedirected = IsHandleRedirected(STD_OUTPUT_HANDLE);
1279:     errRedirected = IsHandleRedirected(STD_ERROR_HANDLE);
1280: 
1281:     if (outRedirected && errRedirected)
1282:     {
1283:         /* Both standard output and error handles are redirected.
1284:          * There is no point in attaching to parent process console.
1285:          */
1286:         return;
1287:     }
1288: 
1289:     if (AttachConsole(ATTACH_PARENT_PROCESS) == 0)
1290:     {
1291:         /* Console attach failed. */
1292:         return;
1293:     }
1294: 
1295:     if (inHandle != GetStdHandle(STD_INPUT_HANDLE))
1296:     {
1297:         /* Restore input handle. */
1298:         SetStdHandle(STD_INPUT_HANDLE, inHandle);
1299:     }
1300: 
1301:     /* Console attach succeded */
1302:     if (outRedirected == FALSE)
1303:     {
1304:         freopen("CONOUT$", "w", stdout);
1305:     }
1306:     else if (GetStdHandle(STD_OUTPUT_HANDLE) != outHandle)
1307:     {
1308:         /* Attach Console changed STD_OUTPUT_HANDLE even though it is redirected.
1309:          * Restore the redirected handle.
1310:          */
1311:         SetStdHandle(STD_OUTPUT_HANDLE, outHandle);
1312:     }
1313: 
1314:     if (errRedirected == FALSE)
1315:     {
1316:         freopen("CONOUT$", "w", stderr);
1317:     }
1318:     else if (GetStdHandle(STD_ERROR_HANDLE) != errHandle)
1319:     {
1320:         /* Attach Console changed STD_ERROR_HANDLE even though it is redirected.
1321:          * Restore the redirected handle.
1322:          */
1323:         SetStdHandle(STD_ERROR_HANDLE, errHandle);
1324:     }
