191: static ULONG GetDeviceTypeToUse(PDEVICE_OBJECT pdo)
192: {
193:     PDEVICE_OBJECT ldo = IoGetAttachedDeviceReference(pdo);
194:     ULONG devtype = FILE_DEVICE_UNKNOWN;
195: 
196:     if (ldo != NULL)
197:     {
198:         devtype = ldo->DeviceType;
199:         ObDereferenceObject(ldo);
200:     }
201: 
202:     return devtype;
203: }
